using System.Buffers.Binary;
using System.Security.Cryptography;
using System.Text;
using DotJpegli.Internal;
using Xunit;
using static DotJpegli.Tests.EncoderProgressiveTests;

namespace DotJpegli.Tests;

public sealed class AdditionalGrayscaleIccProfileTests
{
    // Complete profiles independently generated by an MSVC C++17 /fp:strict /O2
    // probe calling MaybeCreateProfile from the unchanged upstream CMS header at
    // google/jpegli 031a0077f5799a6041004267fc12b956c1f52a20 with GRAY,
    // perceptual intent, D65 (DCI white for DCI), and the named transfer function.
    private static readonly string[] NativeSha256 =
    [
        "2955B00FF8629C6C518509DC1F31279828D00508B096F4EB9565D271849CBB81",
        "E3D49DE1DEE11786DBA14DE3F273B1CBBC86FD5501F3DC42CD393F737ACE82FB",
        "1F25816054A452DD533EF8F56203506387A9521474225B59DEB3D8D91F51BF58",
        "0EA7002A458B45560E4FA1B9FA8B99115C2CFB5468DCA8FE494480E6D093E013"
    ];
    private static readonly string[] NativeId =
    [
        "40AB32E3684939CF0CB29EB2C82798F5", "C20C5B4FA3DD24109E6DA3D52288B148",
        "5713614D083B44B7CEA46698FE2DAF5F", "6B40A764E4E988F46E9F399DE140CA8C"
    ];
    private static readonly string[] Descriptions =
        ["Gra_D65_Per_709", "Gra_DCI_Per_DCI", "Gra_D65_Per_PeQ", "Gra_D65_Per_HLG"];
    private static readonly byte[] OpaqueProfile = [0x01, 0x23, 0x45, 0x67];

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(3)]
    public void MatchesTheCompletePinnedNativeProfileAndOwnsItsStorage(int kind)
    {
        byte[] profile = Create(kind), second = Create(kind);
        Assert.Equal(kind < 2 ? 328 : 436, profile.Length);
        Assert.Equal(NativeSha256[kind], Convert.ToHexString(SHA256.HashData(profile)));
        Assert.Equal(NativeId[kind], Convert.ToHexString(profile.AsSpan(84, 16)));
        Assert.NotSame(profile, second);
        Assert.Equal(profile, second);
        Array.Fill(profile, (byte)0xdd);
        Assert.Equal(NativeSha256[kind], Convert.ToHexString(SHA256.HashData(second)));
        Assert.Equal(second, Create(kind));
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(3)]
    public void HeaderAndAlignedTagsDescribeTheGrayscaleDisplayProfile(int kind)
    {
        byte[] profile = Create(kind);
        Assert.Equal(profile.Length, Int32(profile, 0));
        Assert.Equal("jxl ", Signature(profile, 4));
        Assert.Equal(0x04400000, Int32(profile, 8));
        Assert.Equal("mntr", Signature(profile, 12));
        Assert.Equal("GRAY", Signature(profile, 16));
        Assert.Equal("XYZ ", Signature(profile, 20));
        Assert.Equal(new[] { 2019, 12, 1, 0, 0, 0 },
            Enumerable.Range(0, 6).Select(index => UInt16(profile, 24 + index * 2)));
        Assert.Equal("acsp", Signature(profile, 36));
        Assert.Equal("APPL", Signature(profile, 40));
        Assert.All(profile[44..64], value => Assert.Equal(0, value));
        Assert.Equal(0, Int32(profile, 64)); // Perceptual rendering intent.
        // D50 PCS illumination differs from the unadapted grayscale media white.
        Assert.Equal(0x0000f6d6, Int32(profile, 68));
        Assert.Equal(0x00010000, Int32(profile, 72));
        Assert.Equal(0x0000d32d, Int32(profile, 76));
        Assert.Equal("jxl ", Signature(profile, 80));
        Assert.All(profile[100..128], value => Assert.Equal(0, value));

        Dictionary<string, Tag> tags = Tags(profile);
        Assert.Equal(new[] { "cprt", "desc", "kTRC", "wtpt" }, tags.Keys.Order());
        Assert.Equal(Descriptions[kind], Text(profile, tags["desc"]));
        Assert.Equal("CC0", Text(profile, tags["cprt"]));
        Tag white = tags["wtpt"];
        Assert.Equal("XYZ ", Signature(profile, white.Offset));
        Assert.Equal(20, white.Length);
        double x = kind == 1 ? 0.314 : 0.3127, y = kind == 1 ? 0.351 : 0.3290;
        double[] expectedWhite = [x / y, 1, (1 - x - y) / y];
        for (int channel = 0; channel < expectedWhite.Length; channel++)
            AssertClose(expectedWhite[channel], Fixed(profile, white.Offset + 8 + channel * 4),
                0.5 / 65536, $"media white channel {channel}");
        // GRAY omits CICP even for named HDR transfer functions. Inference stays
        // unspecified instead of inferring from the description or kTRC.
        Assert.Equal(2, IccProfile.LookupTransferFunction(profile, TestContext.Current.CancellationToken));
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(3)]
    public void ProfileIdIsTheIndependentIccMd5Digest(int kind)
    {
        byte[] profile = Create(kind), id = profile[84..100];
        Array.Clear(profile, 44, 4);
        Array.Clear(profile, 64, 4);
        Array.Clear(profile, 84, 16);
        Assert.Equal(id, MD5.HashData(profile));
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    public void ParsedParametricCurveMatchesAnIndependentDecodingOracle(int kind)
    {
        byte[] profile = Create(kind);
        Tag curve = Tags(profile)["kTRC"];
        Assert.Equal(32, curve.Length);
        Assert.Equal("para", Signature(profile, curve.Offset));
        Assert.Equal(3, UInt16(profile, curve.Offset + 8));
        Assert.Equal(0, UInt16(profile, curve.Offset + 10));
        double[] expected = kind == 0
            ? [1 / 0.45, 1 / 1.099, 0.099 / 1.099, 1 / 4.5, 0.081]
            : [2.6, 1, 0, 1, 0];
        for (int index = 0; index < expected.Length; index++)
            AssertClose(expected[index], Fixed(profile, curve.Offset + 12 + index * 4),
                0.5 / 65536, $"curve parameter {index}");

        double threshold = Fixed(profile, curve.Offset + 28);
        double[] boundaries = [0, 0.001, 0.01, 0.08099999, 0.081, 0.08100001,
            threshold - 1e-8, threshold, threshold + 1e-8, 0.125, 0.25, 0.5, 0.75, 1];
        foreach (double encoded in Enumerable.Range(0, 256).Select(value => value / 255.0)
            .Concat(boundaries.Where(value => value >= 0)))
        {
            double linear = kind == 0
                ? encoded < 0.081 ? encoded / 4.5 : Math.Pow((encoded + 0.099) / 1.099, 1 / 0.45)
                : Math.Pow(encoded, 2.6);
            // BT.709's rounded decimal constants produce a small discontinuity
            // at the breakpoint; the serialized 16.16 threshold can select its
            // other branch in a tiny interval around 0.081.
            double tolerance = kind == 0 && Math.Abs(encoded - 0.081) < 0.00001 ? 0.00007 : 0.00003;
            AssertClose(linear, EvaluateCurve(profile, curve, encoded), tolerance,
                $"linear gray at encoded sample {encoded:R}");
        }
        Assert.Equal(0, EvaluateCurve(profile, curve, 0));
        AssertClose(1, EvaluateCurve(profile, curve, 1), 0.00003, "linear white");
    }

    [Theory]
    [InlineData(2)]
    [InlineData(3)]
    public void ParsedHdrTableHasMonotoneUntoneMappedNodesAndLinearInterpolation(int kind)
    {
        byte[] profile = Create(kind);
        Tag curve = Tags(profile)["kTRC"];
        Assert.Equal("curv", Signature(profile, curve.Offset));
        Assert.Equal(140, curve.Length);
        Assert.Equal(64, Int32(profile, curve.Offset + 8));
        Assert.Equal(0, UInt16(profile, curve.Offset + 12));
        Assert.Equal(65535, UInt16(profile, curve.Offset + 12 + 63 * 2));
        int previous = -1;
        for (int index = 0; index < 64; index++)
        {
            int actual = UInt16(profile, curve.Offset + 12 + index * 2);
            Assert.InRange(actual, previous, 65535);
            int expected = (int)Math.Round(Math.Clamp(DecodeHdr(kind, index / 63.0), 0, 1) * 65535,
                MidpointRounding.AwayFromZero);
            // The native grid and transfer results are rounded through float;
            // the independent double oracle allows one table unit for that.
            Assert.InRange(actual, Math.Max(0, expected - 1), Math.Min(65535, expected + 1));
            previous = actual;
        }

        for (int index = 0; index < 256; index++)
        {
            double encoded = index / 255.0, position = encoded * 63;
            int lower = Math.Min(62, (int)position);
            double fraction = position - lower;
            double expected = DecodeHdr(kind, lower / 63.0) * (1 - fraction)
                + DecodeHdr(kind, (lower + 1) / 63.0) * fraction;
            AssertClose(expected, EvaluateCurve(profile, curve, encoded), 2.0 / 65535,
                $"interpolated gray at encoded HDR sample {encoded:R}");
        }
        // PQ is normalized to 10,000 nits without the RGB profile's 250-nit
        // tone mapping; HLG uses the inverse OETF with system gamma 1. These
        // midtones would differ substantially after either HDR RGB LUT path.
        Assert.InRange(EvaluateCurve(profile, curve, 0.5),
            kind == 2 ? 0.009 : 0.0833, kind == 2 ? 0.0095 : 0.0838);
        Assert.InRange(EvaluateCurve(profile, curve, 0.75),
            kind == 2 ? 0.098 : 0.264, kind == 2 ? 0.1 : 0.266);
    }

    public static TheoryData<int, int, bool, bool, int, bool> EncodingModes
    {
        get
        {
            var modes = new TheoryData<int, int, bool, bool, int, bool>();
            for (int profile = 0; profile < 4; profile++)
            {
                modes.Add(profile, 0, false, false, 0, false);
                modes.Add(profile, 1, false, true, 0, true);
                modes.Add(profile, 2, false, true, 2, false);
                modes.Add(profile, 0, true, true, 2, true);
                modes.Add(profile, 1, true, false, 0, true);
                modes.Add(profile, 2, true, true, 0, false);
            }
            return modes;
        }
    }

    [Theory]
    [MemberData(nameof(EncodingModes))]
    public void ExplicitProfileEmbedsExactBytesWithoutChangingGrayCodingOrInputStorage(
        int profileKind, int sampleKind, bool converted, bool progressive, int refinement, bool optimize)
    {
        const int width = 19, height = 17;
        int components = converted ? 4 : 1, stride = width * components + 5;
        Array pixels = Source(sampleKind, converted, width, height, stride);
        Array originalPixels = (Array)pixels.Clone();
        PixelComponentLayout layout = converted ? PixelComponentLayout.Bgra : PixelComponentLayout.Gray;
        byte[] profile = Create(profileKind);
        byte[] backing = Enumerable.Repeat((byte)0x5b, profile.Length + 11).ToArray();
        profile.CopyTo(backing, 3);
        byte[] originalBacking = backing.ToArray();
        var options = new JpegliEncoderOptions
        {
            ColorSpace = JpegColorSpace.Grayscale, IccProfile = backing.AsMemory(3, profile.Length),
            InferCicpTransferFunctionFromIccProfile = true, Distance = 1.375f,
            SmoothingFactor = 37, Progressive = progressive, OptimizeHuffmanTables = optimize,
            ProgressiveRefinementBits = refinement, RestartInterval = 2
        };
        byte[] actual = Encode(pixels, width, height, stride, layout, options);
        (byte[] embedded, byte[] coding) = ReadIccAndCoding(actual);
        Assert.Equal(profile, embedded);
        byte[] opaque = Encode(pixels, width, height, stride, layout,
            options with { IccProfile = OpaqueProfile, InferCicpTransferFunctionFromIccProfile = false });
        Assert.Equal(ReadIccAndCoding(opaque).Coding, coding);
        Assert.Equal(actual, Encode(pixels, width, height, stride, layout,
            options with { InferCicpTransferFunctionFromIccProfile = false }));
        if (!converted)
            Assert.Equal(actual, Encode(pixels, width, height, stride, layout,
                options with { ColorSpace = JpegColorSpace.Automatic }));
        // Independent entropy parsing validates the component, restart markers,
        // Huffman coding and baseline/progressive/refinement scan script.
        JpegDocument document = JpegDocument.Read(actual, progressive, 2, refinement);
        Assert.Equal(width, document.Width);
        Assert.Equal(height, document.Height);
        Assert.Equal(1, Assert.Single(document.Components).Key);
        Assert.All(document.Scans.SelectMany(scan => scan.Selectors), selector => Assert.Equal(1, selector.Component));
        using var destination = new MemoryStream();
        using var output = new WriteOnlyStream(destination);
        Encode(output, pixels, width, height, stride, layout, options, TestContext.Current.CancellationToken);
        Assert.Equal(actual, destination.ToArray());
        Assert.False(output.Closed);
        Assert.Equal(originalBacking, backing);
        Assert.Equal(originalPixels.Cast<object>(), pixels.Cast<object>());
    }

    [Theory]
    [InlineData(0, 16)]
    [InlineData(0, 18)]
    [InlineData(1, 16)]
    [InlineData(1, 18)]
    [InlineData(2, 16)]
    [InlineData(2, 18)]
    [InlineData(3, 16)]
    [InlineData(3, 18)]
    public void ExplicitHdrHintOverridesUnspecifiedInferenceWithoutTransformingSamples(int kind, int transfer)
    {
        const int width = 19, height = 17, stride = width + 5;
        Array pixels = Source(2, false, width, height, stride);
        byte[] profile = Create(kind);
        var options = new JpegliEncoderOptions
        {
            IccProfile = profile, InferCicpTransferFunctionFromIccProfile = true,
            CicpTransferFunction = transfer, Distance = 2.375f, AdaptiveQuantization = false,
            Progressive = true, ProgressiveRefinementBits = 2, RestartInterval = 2
        };
        byte[] hinted = Encode(pixels, width, height, stride, PixelComponentLayout.Gray, options);
        Assert.Equal(hinted, Encode(pixels, width, height, stride, PixelComponentLayout.Gray,
            options with { InferCicpTransferFunctionFromIccProfile = false }));
        (byte[] embedded, byte[] coding) = ReadIccAndCoding(hinted);
        Assert.Equal(profile, embedded);
        Assert.Equal(coding, ReadIccAndCoding(Encode(pixels, width, height, stride, PixelComponentLayout.Gray,
            options with { IccProfile = OpaqueProfile, InferCicpTransferFunctionFromIccProfile = false })).Coding);
        byte[] unhinted = Encode(pixels, width, height, stride, PixelComponentLayout.Gray,
            options with { CicpTransferFunction = 2 });
        Assert.False(JpegDocument.Read(hinted, true, 2, 2).Quantizers[0]
            .SequenceEqual(JpegDocument.Read(unhinted, true, 2, 2).Quantizers[0]));
        Assert.Equal(2, IccProfile.LookupTransferFunction(profile, TestContext.Current.CancellationToken));
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(3)]
    public void CancellationBeforeOrAfterTheIccMarkerLeavesTheNonseekableStreamOpen(int kind)
    {
        byte[] pixels = [0, 127, 255], profile = Create(kind);
        var options = new JpegliEncoderOptions { IccProfile = profile, InferCicpTransferFunctionFromIccProfile = true };
        byte[] complete = Encode(pixels, 3, 1, 3, PixelComponentLayout.Gray, options);
        using var destination = new MemoryStream();
        using (var output = new WriteOnlyStream(destination))
        {
            var canceled = new CancellationToken(true);
            var error = Assert.Throws<OperationCanceledException>(() =>
                Encode(output, pixels, 3, 1, 3, PixelComponentLayout.Gray, options, canceled));
            Assert.Equal(canceled, error.CancellationToken);
            Assert.Equal(0, destination.Length);
            Assert.False(output.Closed);
        }
        int boundary = IccMarkerEnd(complete);
        using var cancellation = CancellationTokenSource.CreateLinkedTokenSource(TestContext.Current.CancellationToken);
        using var stream = new WriteOnlyStream(destination, () =>
        {
            if (destination.Length >= boundary)
                cancellation.Cancel();
        });
        var interrupted = Assert.Throws<OperationCanceledException>(() =>
            Encode(stream, pixels, 3, 1, 3, PixelComponentLayout.Gray, options, cancellation.Token));
        Assert.Equal(cancellation.Token, interrupted.CancellationToken);
        Assert.Equal(complete[..boundary], destination.ToArray());
        Assert.False(stream.Closed);
        Assert.Equal(Create(kind), profile);
    }

    private static byte[] Create(int kind) => kind switch
    {
        0 => JpegliIccProfiles.CreateRec709GrayscaleProfile(),
        1 => JpegliIccProfiles.CreateDciGrayscaleProfile(),
        2 => JpegliIccProfiles.CreateRec2100PqGrayscaleProfile(),
        _ => JpegliIccProfiles.CreateRec2100HlgGrayscaleProfile()
    };

    private static Array Source(int kind, bool converted, int width, int height, int stride)
    {
        int components = converted ? 4 : 1, rowLength = width * components;
        byte[] bytes = Enumerable.Repeat((byte)0xad, (height - 1) * stride + rowLength).ToArray();
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                for (int channel = 0; channel < (converted ? 3 : 1); channel++)
                    bytes[y * stride + x * components + channel] = (byte)((x * 73 + y * 29 + channel * 61) % 256);
        return kind switch
        {
            0 => bytes,
            1 => bytes.Select((value, index) => (ushort)Math.Clamp(value * 257 + index % 47 - 23, 0, 65535)).ToArray(),
            _ => bytes.Select((value, index) => index % stride >= rowLength || converted && index % stride % 4 == 3
                ? float.NaN : Math.Clamp(value / 255f + (index % 47 - 23) / 65535f, 0f, 1f)).ToArray()
        };
    }

    private static Dictionary<string, Tag> Tags(byte[] profile)
    {
        int count = Int32(profile, 128), end = 132 + count * 12;
        Assert.Equal(4, count);
        var result = new Dictionary<string, Tag>();
        var extents = new HashSet<Tag>();
        for (int index = 0; index < count; index++)
        {
            int entry = 132 + index * 12;
            var tag = new Tag(Int32(profile, entry + 4), Int32(profile, entry + 8));
            Assert.Equal(0, tag.Offset % 4);
            Assert.InRange(tag.Offset, end, profile.Length - 8);
            Assert.InRange(tag.Length, 8, profile.Length - tag.Offset);
            Assert.Equal(0, Int32(profile, tag.Offset + 4));
            Assert.True(result.TryAdd(Signature(profile, entry), tag));
            Assert.True(extents.Add(tag));
        }
        Tag[] ordered = extents.OrderBy(tag => tag.Offset).ToArray();
        Assert.Equal(end, ordered[0].Offset);
        for (int index = 1; index < ordered.Length; index++)
        {
            int previousEnd = ordered[index - 1].Offset + ordered[index - 1].Length;
            Assert.Equal((previousEnd + 3) & ~3, ordered[index].Offset);
            Assert.All(profile[previousEnd..ordered[index].Offset], value => Assert.Equal(0, value));
        }
        Assert.Equal(profile.Length, ordered[^1].Offset + ordered[^1].Length);
        return result;
    }

    private static string Text(byte[] profile, Tag tag)
    {
        Assert.Equal("mluc", Signature(profile, tag.Offset));
        Assert.Equal(1, Int32(profile, tag.Offset + 8));
        Assert.Equal(12, Int32(profile, tag.Offset + 12));
        Assert.Equal("enUS", Signature(profile, tag.Offset + 16));
        int length = Int32(profile, tag.Offset + 20), offset = Int32(profile, tag.Offset + 24);
        Assert.Equal(0, length % 2);
        Assert.InRange(offset, 28, tag.Length);
        Assert.InRange(length, 0, tag.Length - offset);
        Assert.All(profile[(tag.Offset + offset + length)..(tag.Offset + tag.Length)], value => Assert.Equal(0, value));
        return Encoding.BigEndianUnicode.GetString(profile, tag.Offset + offset, length);
    }

    private static double DecodeHdr(int kind, double encoded)
    {
        if (kind == 3)
            return encoded <= 0.5 ? encoded * encoded / 3
                : (Math.Exp((encoded - 0.5599107295) / 0.17883277) + 1 - 4 * 0.17883277) / 12;
        double power = Math.Pow(encoded, 1 / (2523.0 / 32));
        return Math.Pow(Math.Max(power - 3424.0 / 4096, 0)
            / (2413.0 / 128 - 2392.0 / 128 * power), 1 / (2610.0 / 16384));
    }

    private static double EvaluateCurve(byte[] profile, Tag curve, double value)
    {
        if (Signature(profile, curve.Offset) == "curv")
        {
            int count = Int32(profile, curve.Offset + 8);
            double position = value * (count - 1);
            int lower = Math.Min(count - 2, (int)position);
            double fraction = position - lower;
            return (UInt16(profile, curve.Offset + 12 + lower * 2) * (1 - fraction)
                + UInt16(profile, curve.Offset + 12 + (lower + 1) * 2) * fraction) / 65535;
        }
        double gamma = Fixed(profile, curve.Offset + 12), a = Fixed(profile, curve.Offset + 16),
            b = Fixed(profile, curve.Offset + 20), c = Fixed(profile, curve.Offset + 24),
            threshold = Fixed(profile, curve.Offset + 28);
        return value >= threshold ? Math.Pow(a * value + b, gamma) : c * value;
    }

    private static (byte[] Icc, byte[] Coding) ReadIccAndCoding(byte[] jpeg)
    {
        Assert.Equal(new byte[] { 0xff, 0xd8 }, jpeg[..2]);
        using var coding = new MemoryStream();
        coding.Write(jpeg.AsSpan(0, 2));
        byte[]? profile = null;
        int offset = 2;
        while (jpeg[offset + 1] != 0xda)
        {
            Assert.Equal(0xff, jpeg[offset]);
            int length = UInt16(jpeg, offset + 2);
            Assert.InRange(length, 2, jpeg.Length - offset - 2);
            int end = offset + 2 + length;
            if (jpeg[offset + 1] == 0xe2)
            {
                Assert.Null(profile);
                Assert.True(jpeg.AsSpan(offset + 4, 12).SequenceEqual("ICC_PROFILE\0"u8));
                Assert.Equal(1, jpeg[offset + 16]);
                Assert.Equal(1, jpeg[offset + 17]);
                profile = jpeg[(offset + 18)..end];
            }
            else
                coding.Write(jpeg.AsSpan(offset, end - offset));
            offset = end;
        }
        coding.Write(jpeg.AsSpan(offset));
        Assert.NotNull(profile);
        return (profile, coding.ToArray());
    }

    private static int IccMarkerEnd(byte[] jpeg)
    {
        int offset = 2;
        while (jpeg[offset + 1] != 0xda)
        {
            int end = offset + 2 + UInt16(jpeg, offset + 2);
            if (jpeg[offset + 1] == 0xe2)
                return end;
            offset = end;
        }
        throw new InvalidDataException("The JPEG has no ICC APP2 marker.");
    }

    private static byte[] Encode(Array source, int width, int height, int stride,
        PixelComponentLayout layout, JpegliEncoderOptions options) => source switch
    {
        byte[] bytes => JpegliEncoder.Encode(bytes, width, height, (PixelLayout)(int)layout,
            options, stride, TestContext.Current.CancellationToken),
        ushort[] words => JpegliEncoder.Encode(words, width, height, layout,
            options, stride, TestContext.Current.CancellationToken),
        _ => JpegliEncoder.Encode((float[])source, width, height, layout,
            options, stride, TestContext.Current.CancellationToken)
    };

    private static void Encode(Stream output, Array source, int width, int height, int stride,
        PixelComponentLayout layout, JpegliEncoderOptions options, CancellationToken cancellationToken)
    {
        if (source is byte[] bytes)
            JpegliEncoder.Encode(output, bytes, width, height, (PixelLayout)(int)layout,
                options, stride, cancellationToken);
        else if (source is ushort[] words)
            JpegliEncoder.Encode(output, words, width, height, layout, options, stride, cancellationToken);
        else
            JpegliEncoder.Encode(output, (float[])source, width, height, layout, options, stride, cancellationToken);
    }

    private static int Int32(byte[] data, int offset) => BinaryPrimitives.ReadInt32BigEndian(data.AsSpan(offset, 4));
    private static int UInt16(byte[] data, int offset) => BinaryPrimitives.ReadUInt16BigEndian(data.AsSpan(offset, 2));
    private static double Fixed(byte[] data, int offset) => Int32(data, offset) / 65536.0;
    private static string Signature(byte[] data, int offset) => Encoding.ASCII.GetString(data, offset, 4);
    private sealed record Tag(int Offset, int Length);

    private static void AssertClose(double expected, double actual, double tolerance, string label) =>
        Assert.True(double.IsFinite(actual) && Math.Abs(expected - actual) <= tolerance,
            $"{label}: expected {expected:R}, actual {actual:R}, tolerance {tolerance:R}.");
}
